mapper.select:
SELECT GC.GROUP_CODE , GC.GROUP_CODE_NAME , GC.GROUP_CODE_DESC AS GROUP_CODE_DESCRIPTION , GC.DATA_STATUS , GC.SORT_ORDER , GC.CREATED_BY , GC.CREATED_AT , GC.UPDATED_BY , GC.UPDATED_AT FROM TB_GROUP_CODE GC WHERE TRUE
AND GC.GROUP_CODE IN
#{groupCode}
AND GC.GROUP_CODE = #{groupCode}
AND GC.GROUP_CODE_NAME LIKE CONCAT('%', #{groupCodeName}, '%')
AND EXISTS ( SELECT 1 FROM TB_COMMON_CODE CC WHERE CC.GROUP_CODE = GC.GROUP_CODE AND CC.DATA_STATUS != 'DELETED' AND CC.COMMON_CODE_NAME LIKE CONCAT('%', #{commonCodeName}, '%') )
AND GC.DATA_STATUS = #{dataStatus}
AND GC.DATA_STATUS != 'DELETED'
ORDER BY GC.SORT_ORDER

SELECT GC.GROUP_CODE , GC.GROUP_CODE_NAME , GC.GROUP_CODE_DESC AS GROUP_CODE_DESCRIPTION , GC.DATA_STATUS , GC.SORT_ORDER , GC.CREATED_BY , GC.CREATED_AT , GC.UPDATED_BY , GC.UPDATED_AT , CC.GROUP_CODE AS COMMON_CODE_GROUP_CODE , CC.COMMON_CODE , CC.COMMON_CODE_NAME , CC.COMMON_CODE_DESC AS COMMON_CODE_DESCRIPTION , CC.DATA_STATUS AS COMMON_CODE_DATA_STATUS , CC.SORT_ORDER AS COMMON_CODE_SORT_ORDER , CC.CREATED_AT AS COMMON_CODE_CREATED_AT , CC.CREATED_BY AS COMMON_CODE_CREATED_BY , CC.UPDATED_AT AS COMMON_CODE_UPDATED_AT , CC.UPDATED_BY AS COMMON_CODE_UPDATED_BY FROM TB_GROUP_CODE GC LEFT JOIN TB_COMMON_CODE CC ON GC.GROUP_CODE = CC.GROUP_CODE AND CC.DATA_STATUS != 'DELETED' WHERE TRUE
AND GC.GROUP_CODE = #{groupCode}
AND GC.DATA_STATUS = #{dataStatus}
AND GC.DATA_STATUS != 'DELETED'
ORDER BY GC.SORT_ORDER, CC.SORT_ORDER

mapper.insert:
INSERT INTO TB_GROUP_CODE (
    GROUP_CODE
  , GROUP_CODE_NAME
  , GROUP_CODE_DESC
  , DATA_STATUS
  , SORT_ORDER
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{groupCode}
  , #{groupCodeName}
  , #{groupCodeDescription}
  , #{dataStatus}
  , #{sortOrder}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_GROUP_CODE
   SET GROUP_CODE_NAME = #{groupCodeName}
     , GROUP_CODE_DESC = #{groupCodeDescription}
     , DATA_STATUS     = #{dataStatus}
     , UPDATED_BY      = #{author}
     , UPDATED_AT      = NOW()
 WHERE GROUP_CODE      = #{groupCode}
   AND DATA_STATUS    != 'DELETED'

UPDATE TB_COMMON_CODE
   SET DATA_STATUS = #{dataStatus}
     , UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()
 WHERE GROUP_CODE  = #{groupCode}
   AND DATA_STATUS != 'DELETED'

UPDATE TB_GROUP_CODE
   SET DATA_STATUS = 'DELETED'
     , UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()
 WHERE GROUP_CODE  = #{groupCode}

UPDATE TB_COMMON_CODE
   SET DATA_STATUS = 'DELETED'
     , UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()
 WHERE GROUP_CODE  = #{groupCode}
